request_hints = ('movie', 'film', 'recommend', 'watch', 'note', 'title')
request_candidates = []
for contact in leslie_contact_candidates:
    for message_row in messages_by_contact_number[contact['phone_number']]:
        if message_row['sender']['phone_number'] == contact['phone_number']:
            lowered_message = message_row['message'].casefold()
            relevance = sum(1 for hint in request_hints if hint in lowered_message)
            request_candidates.append((relevance, message_row['sent_at'], message_row['text_message_id'], contact, message_row))
if not request_candidates:
