if not all_note_details:
    raise RuntimeError('No Simple Note records were found')
def normalized_words(value):
    return ''.join(ch.lower() if ch.isalnum() else ' ' for ch in str(value)).split()
stop_words = {'a', 'an', 'and', 'are', 'as', 'at', 'be', 'can', 'could', 'for', 'from', 'has', 'have', 'i', 'in', 'is', 'it', 'list', 'me', 'my', 'of', 'on', 'please', 'send', 'some', 'that', 'the', 'them', 'to', 'via', 'with', 'you', 'your'}
movie_words = {'cinema', 'film', 'films', 'movie', 'movies', 'recommend', 'recommendation', 'recommendations', 'watch', 'watchlist'}
normalized_request = ' '.join(normalized_words(leslie_request_message['message']))
request_terms = set(normalized_words(leslie_request_message['message'])) - stop_words
ranked_notes = []
for note in all_note_details:
    metadata_text = note['title'] + ' ' + ' '.join(note['tags'])
    metadata_terms = set(normalized_words(metadata_text))
    content_terms = set(normalized_words(note['content']))
    normalized_title = ' '.join(normalized_words(note['title']))
    title_phrase_bonus = 100 if normalized_title and len(normalized_title) >= 4 and normalized_title in normalized_request else 0
    metadata_overlap = len(request_terms & metadata_terms)
    content_overlap = len(request_terms & content_terms)
    movie_metadata_bonus = 15 if metadata_terms & movie_words else 0
    relevance_score = title_phrase_bonus + 20 * metadata_overlap + 2 * content_overlap + movie_metadata_bonus
    ranked_notes.append((relevance_score, note['updated_at'], note['note_id'], note))
_, _, selected_note_id, selected_note = max(ranked_notes, key=lambda row: (row[0], row[1], row[2]))
raw_content = selected_note['content'].strip().replace('\r\n', '\n').replace('\r', '\n').replace(';', '\n')
raw_items = [item.strip() for item in raw_content.split('\n') if item.strip()]
if len(raw_items) == 1 and ',' in raw_items[0]:
    raw_items = [item.strip() for item in raw_items[0].split(',') if item.strip()]
def clean_movie_item(item):
    value = item.strip()
    changed = True
    while changed:
        changed = False
        for prefix in ('- ', '* ', '• '):
            if value.startswith(prefix):
                value = value[len(prefix):].strip()
                changed = True
        for prefix in ('[ ] ', '[x] ', '[X] '):
            if value.startswith(prefix):
                value = value[len(prefix):].strip()
                changed = True
    for delimiter in ('. ', ') '):
        head, separator, tail = value.partition(delimiter)
        if separator and head.strip().isdigit():
            value = tail.strip()
            break
    value = value.strip(' \t\"\'')
    prefix, separator, tail = value.partition(':')
    if separator and set(normalized_words(prefix)) & movie_words:
        value = tail.strip()
    return value
selected_title_normalized = ' '.join(normalized_words(selected_note['title']))
movie_titles = []
seen_movie_titles = set()
for raw_item in raw_items:
    cleaned_item = clean_movie_item(raw_item)
    cleaned_normalized = ' '.join(normalized_words(cleaned_item))
    if not cleaned_item or raw_item.rstrip().endswith(':') or cleaned_normalized == selected_title_normalized:
        continue
    dedupe_key = cleaned_item.casefold()
    if dedupe_key not in seen_movie_titles:
        seen_movie_titles.add(dedupe_key)
        movie_titles.append(cleaned_item)
if not movie_titles:
    raise RuntimeError('The selected note did not yield any movie titles')
outbound_message = ', '.join(movie_titles)
print({'recipient': {'contact_id': selected_leslie_contact['contact_id'], 'phone_number': selected_leslie_contact['phone_number']}, 'source_request': leslie_request_message['message'], 'selected_note': {'note_id': selected_note_id, 'title': selected_note['title']}, 'movie_titles': movie_titles, 'outbound_message': outbound_message})
